<?php require __DIR__.'/../bootstrap.php';require_admin();require __DIR__.'/../config/orders.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$action=$_POST['action']??'';if($action==='add'){ $name=trim($_POST['name']??'');$price=input($_POST,'price');$stock=filter_var($_POST['stock']??'',FILTER_VALIDATE_INT);$cat=(int)($_POST['category_id']??0);if(!$name||strlen($name)>200||!preg_match('/^[0-9]{1,10}(\.[0-9]{1,2})?$/D',$price)||$stock===false||$stock<0||$stock>2147483647||$cat<1)throw new InvalidArgumentException('Invalid product');$image=trim(input($_POST,'image_url'));if(strlen($image)>500||($image!==''&&(!filter_var($image,FILTER_VALIDATE_URL)||!in_array(strtolower(parse_url($image,PHP_URL_SCHEME)??''),['http','https'],true))))throw new InvalidArgumentException('Use an HTTP or HTTPS image URL');$category=db()->prepare('SELECT id FROM categories WHERE id=?');$category->execute([$cat]);if(!$category->fetchColumn())throw new InvalidArgumentException('Choose an existing category');$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($name)).'-'.bin2hex(random_bytes(3));$s=db()->prepare('INSERT INTO products(category_id,name,slug,description,price,stock,image_url) VALUES(?,?,?,?,?,?,?)');$s->execute([$cat,$name,$slug,trim($_POST['description']??''),$price,$stock,$image]);}elseif($action==='stock'){ $stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);if($stock===false||$stock<0||$stock>2147483647)throw new InvalidArgumentException('Invalid stock quantity'); $s=db()->prepare('UPDATE products SET stock=? WHERE id=?');$s->execute([$stock,(int)$_POST['id']]);}elseif($action==='status'){$valid=['pending','processing','shipped','delivered','cancelled'];if(!in_array($_POST['status']??'',$valid,true))throw new InvalidArgumentException('Invalid status');change_order_status(db(),(int)($_POST['id']??0),$_POST['status']);}elseif($action==='payment'){$valid=['unpaid','pending_verification','paid','refunded'];if(!in_array($_POST['status']??'',$valid,true))throw new InvalidArgumentException('Invalid payment status');$s=db()->prepare('UPDATE payments SET status=? WHERE order_id=?');$s->execute([$_POST['status'],(int)$_POST['id']]);}else{throw new InvalidArgumentException('Invalid admin action');}redirect('index.php');}catch(Throwable $e){$error=request_error($e,'admin/index.php failed');}}$cats=db()->query('SELECT * FROM categories')->fetchAll();$products=db()->query('SELECT id,name,price,stock FROM products ORDER BY id DESC')->fetchAll();$orders=db()->query('SELECT o.id,o.total,o.status,u.email,p.status payment_status FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN payments p ON p.order_id=o.id ORDER BY o.id DESC LIMIT 50')->fetchAll();?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>PC Forge Admin</title></head><body><header class="top"><a class="brand" href="../index.php">PC<span>FORGE</span> / Admin</a><a href="../index.php">← Storefront</a></header><main class="wrap"><h1>Admin dashboard</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><h2>Add product</h2><form method="post" class="panel stack wide"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add"><input name="name" placeholder="Product name" required><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><textarea name="description" placeholder="Description"></textarea><input name="price" type="number" step="0.01" min="0" placeholder="Price" required><input name="stock" type="number" min="0" placeholder="Stock" required><input name="image_url" placeholder="Image URL"><button class="btn">Add product</button></form><h2>Inventory</h2><div class="panel"><table class="table"><tr><th>Product</th><th>Price</th><th>Stock</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td>₱<?=number_format($p['price'],2)?></td><td><form method="post" class="flex"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="stock"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="number" min="0" name="stock" value="<?=$p['stock']?>" style="width:85px"><button class="btn alt">Save</button></form></td></tr><?php endforeach;?></table></div><h2>Recent orders</h2><div class="panel"><table class="table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Order status</th><th>Payment</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['email'])?></td><td>₱<?=number_format($o['total'],2)?></td><td><form method="post" class="flex"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" style="width:145px"><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $v):?><option <?=$o['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn alt">Save</button></form></td><td><form method="post" class="flex"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" style="width:175px"><?php foreach(['unpaid','pending_verification','paid','refunded'] as $v):?><option <?=$o['payment_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn alt">Save</button></form></td></tr><?php endforeach;?></table></div></main></body></html>